-- Checklists réutilisables (comme Flashquotes) : brief du jour J en 6 étapes et tâches admin datées J-x / J+x.
CREATE TABLE IF NOT EXISTS eywa_crm_checklists (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('brief','admin')), name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', is_default INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS eywa_crm_checklist_items (id TEXT PRIMARY KEY, checklist_id TEXT NOT NULL, stage TEXT NOT NULL DEFAULT '', label TEXT NOT NULL, quantity REAL, unit TEXT NOT NULL DEFAULT '', offset_days INTEGER NOT NULL DEFAULT 0, position INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS eywa_crm_checklist_items_by_list ON eywa_crm_checklist_items(checklist_id,position);
CREATE TABLE IF NOT EXISTS eywa_crm_brief_items (id TEXT PRIMARY KEY, event_id TEXT NOT NULL, stage TEXT NOT NULL, label TEXT NOT NULL, quantity REAL, unit TEXT NOT NULL DEFAULT '', done INTEGER NOT NULL DEFAULT 0, position INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS eywa_crm_brief_items_by_event ON eywa_crm_brief_items(event_id,stage,position);
